namespace Furvo.Presentation;
public partial class Main
{
    private Guid? _trainingTeam;
    private int _trainingTab;
    private DateOnly? _trainingWeek;
    private string SportsPath=>_careers!.PathFor(_workspace!.Career.Id);
    private SqliteSportsStore Sports()=>new(SportsPath);
    private IReadOnlyList<ClubTeam> SportsTeams()=>new SqliteClubSquadStore(SportsPath).Teams();
    private Guid SportsTeam=>_trainingTeam??_workspace!.Career.ClubId!.Value.Value;
    private void SportsTeamSelector(VBoxContainer body,Action refresh)
    {
        var teams=SportsTeams();if(!teams.Any(t=>t.Id==SportsTeam))_trainingTeam=teams[0].Id;var selector=new OptionButton{Name="SportsTeamSelector",SizeFlagsHorizontal=SizeFlags.ExpandFill,CustomMinimumSize=new Vector2(0,34)};foreach(var team in teams)selector.AddItem(team.Name);selector.Selected=teams.ToList().FindIndex(t=>t.Id==SportsTeam);body.AddChild(selector);selector.ItemSelected+=i=>{_trainingTeam=teams[(int)i].Id;refresh();};
    }
    private static VBoxContainer SportsCard(Control parent,string key)
    {
        var body=ClubUi.Card(parent,key);var generated=body.GetChild(0);body.RemoveChild(generated);generated.QueueFree();return body;
    }
    private void SportsError(Exception error,Label status){GD.PushWarning(error.ToString());status.Text=error.Message;}
    /// <summary>Planificar no ejecuta sesiones ni avanza la fecha. La misma pantalla sirve a todos los equipos del club.</summary>
    private void ShowTraining()
    {
        try
        {
            _workspace!.Open(CareerPage.Training);var service=Sports();var team=SportsTeam;var plan=service.Plan(team);var players=new SqliteClubSquadStore(SportsPath).Candidates(team);var staff=service.Staff(team);var today=service.CareerDate();
            var body=Frame("CareerSection",UiText.Get("NavPage_Training"),UiText.Get("TrainingClockNotice"));body.Name="TrainingPage";SportsTeamSelector(body,ShowTraining);
            var tabs=new HFlowContainer{Name="TrainingTabs"};body.AddChild(tabs);for(var i=0;i<6;i++){var index=i;var b=WindowUi.Button("TrainingTab_"+i,()=>{_trainingTab=index;ShowTraining();});if(i==_trainingTab)b.AddThemeColorOverride("font_color",_accent);tabs.AddChild(b);}
            var content=ClubUi.ScrollBody(body,"TrainingScroll");var status=ClubUi.Text("TrainingStatus",plan.RequiresReview?UiText.Get("TrainingReviewRequired"):UiText.Get("TrainingProvisional"),13,"f1b96b");content.AddChild(status);
            bool Save(TrainingPlan next){try{service.SavePlan(next with{RequiresReview=false});ShowTraining();return true;}catch(Exception e){SportsError(e,status);return false;}}
            var week=_trainingWeek??today;week=week.AddDays(-((7+(int)week.DayOfWeek-1)%7));_trainingWeek=week;var weekRow=new HBoxContainer();content.AddChild(weekRow);weekRow.AddChild(WindowUi.Button("TrainingPreviousWeek",()=>{_trainingWeek=week.AddDays(-7);ShowTraining();}));weekRow.AddChild(ClubUi.Text("TrainingWeek",week.ToString("dd/MM/yyyy")+" – "+week.AddDays(6).ToString("dd/MM/yyyy"),17));weekRow.AddChild(WindowUi.Button("TrainingNextWeek",()=>{_trainingWeek=week.AddDays(7);ShowTraining();}));
            var area=_trainingTab switch{1=>TrainingArea.Field,2=>TrainingArea.Gym,3=>TrainingArea.Goalkeepers,4=>TrainingArea.SetPieces,5=>TrainingArea.Recovery,_=>(TrainingArea?)null};
            Guid? editing=null;Action<TrainingSession>? editSession=null;
            var sessions=plan.Sessions.Where(s=>s.Date>=week&&s.Date<=week.AddDays(6)&&(!area.HasValue||TrainingCatalog.Get(s.Exercise).Area==area||area==TrainingArea.Field&&TrainingCatalog.Get(s.Exercise).Area==TrainingArea.Technology)).OrderBy(s=>s.Begins).ToArray();
            foreach(var day in Enumerable.Range(0,7).Select(n=>week.AddDays(n))){var card=SportsCard(content,"TrainingDay_"+day.ToString("yyyyMMdd"));card.AddChild(ClubUi.Text("TrainingDayHeading",day.ToString("dddd dd/MM",CultureInfo.GetCultureInfo("es-ES")),16,"f1b96b"));var selected=sessions.Where(s=>s.Date==day).ToArray();if(selected.Length==0)card.AddChild(ClubUi.Text("TrainingDayEmpty",UiText.Get("TrainingNoSessions"),13,"a6b6ca"));foreach(var session in selected){var line=new HFlowContainer();card.AddChild(line);line.AddChild(ClubUi.Text("TrainingSession_"+session.Id,session.Start.ToString("HH:mm")+" · "+session.Minutes+" min · "+UiText.Get("Exercise_"+session.Exercise)+" · "+UiText.Get("TrainingLoad_"+session.Load)+" · "+session.Participants.Count,14));line.AddChild(WindowUi.Button("TrainingEditSession",()=>editSession?.Invoke(session)));line.AddChild(WindowUi.Button("TrainingDeleteSession",()=>Save(plan with{Sessions=plan.Sessions.Where(s=>s.Id!=session.Id).ToArray()})));}}
            var section=SportsCard(content,"TrainingCreate");section.AddChild(ClubUi.Text("TrainingCreateTitle",UiText.Get("TrainingCreateTitle"),18,"f1b96b"));
            var date=new LineEdit{Name="TrainingDate",Text=(week<today?today:week).ToString("yyyy-MM-dd"),PlaceholderText=UiText.Get("SportsDateFormat")};section.AddChild(date);var time=new LineEdit{Name="TrainingTime",Text="09:00",PlaceholderText=UiText.Get("SportsTimeFormat")};section.AddChild(time);var minutes=new SpinBox{Name="TrainingMinutes",MinValue=5,MaxValue=180,Step=5,Value=45};section.AddChild(ClubUi.Text("TrainingDurationLabel",UiText.Get("TrainingDuration"),14));section.AddChild(minutes);
            var exercises=TrainingCatalog.Exercises.Where(e=>!area.HasValue||e.Area==area||area==TrainingArea.Field&&e.Area==TrainingArea.Technology).ToArray();var exercise=new OptionButton{Name="TrainingExercise"};foreach(var e in exercises)exercise.AddItem(UiText.Get("Exercise_"+e.Code));section.AddChild(exercise);
            var intensity=new OptionButton{Name="TrainingIntensity"};foreach(var load in Enum.GetValues<TrainingLoad>())intensity.AddItem(UiText.Get("TrainingLoad_"+load));intensity.Selected=3;section.AddChild(intensity);
            var scope=new OptionButton{Name="TrainingScope"};foreach(var value in Enum.GetValues<TrainingScope>())scope.AddItem(UiText.Get("TrainingScope_"+value));section.AddChild(scope);
            var person=new OptionButton{Name="TrainingPlayer"};foreach(var p in players)person.AddItem(p.Name);section.AddChild(person);var role=new OptionButton{Name="TrainingPosition"};foreach(var p in Enum.GetValues<PlayerRole>())role.AddItem(UiText.Get("Position_"+p));section.AddChild(role);var group=new OptionButton{Name="TrainingGroup"};foreach(var g in plan.Groups)group.AddItem(g.Name);section.AddChild(group);
            void Scope(){person.Visible=scope.Selected==1;role.Visible=scope.Selected==2;group.Visible=scope.Selected==3;}scope.ItemSelected+=_=>Scope();Scope();
            section.AddChild(ClubUi.Text("TrainingExcludedTitle",UiText.Get("TrainingExcluded"),14));var exclude=new ItemList{Name="TrainingExcluded",SelectMode=ItemList.SelectModeEnum.Multi,CustomMinimumSize=new Vector2(0,110)};foreach(var p in players)exclude.AddItem(p.Name);section.AddChild(exclude);
            var objective=new LineEdit{Name="TrainingObjective",PlaceholderText=UiText.Get("TrainingObjective")};section.AddChild(objective);var frequency=new SpinBox{Name="TrainingFrequency",MinValue=1,MaxValue=52,Step=1,Value=1};section.AddChild(ClubUi.Text("TrainingFrequencyLabel",UiText.Get("TrainingFrequency"),14));section.AddChild(frequency);
            var responsible=new OptionButton{Name="TrainingResponsible"};responsible.AddItem(UiText.Get("TrainingUnassignedResponsible"));foreach(var p in staff)responsible.AddItem(p.Name=="TrainingHeadCoach"?UiText.Get(p.Name):p.Name);section.AddChild(responsible);
            var opposition=new CheckBox{Name="TrainingOpposition",Text=UiText.Get("TrainingOpposition")};section.AddChild(opposition);
            var routine=new OptionButton{Name="TrainingRoutine"};foreach(var kind in Enum.GetValues<Furvo.Core.Tactics.SetPieceKind>())routine.AddItem(UiText.Get("SetPiece_"+kind));section.AddChild(routine);routine.Visible=_trainingTab is 0 or 4;
            editSession=s=>{editing=s.Id;date.Text=s.Date.ToString("yyyy-MM-dd");time.Text=s.Start.ToString("HH:mm");minutes.Value=s.Minutes;exercise.Selected=Array.FindIndex(exercises,e=>e.Code==s.Exercise);intensity.Selected=(int)s.Load;scope.Selected=(int)s.Target.Scope-1;if(s.Target.Player is {} p)person.Selected=players.ToList().FindIndex(a=>a.Id==p);if(s.Target.Position is {} r)role.Selected=(int)r-1;if(s.Target.Group is {} g)group.Selected=plan.Groups.ToList().FindIndex(a=>a.Id==g);exclude.DeselectAll();for(var i=0;i<players.Count;i++)if(s.Target.Excluded?.Contains(players[i].Id)==true)exclude.Select(i,false);objective.Text=s.Objective??"";frequency.Value=s.FrequencyWeeks;responsible.Selected=s.Responsible is {} owner?staff.ToList().FindIndex(a=>a.Id==owner)+1:0;opposition.ButtonPressed=s.Opposition;if(s.Routine is {} configured)routine.Selected=(int)configured.Kind-1;Scope();(content.GetParent() as ScrollContainer)?.EnsureControlVisible(section);};
            section.AddChild(WindowUi.Button("TrainingSaveSession",()=>{try{if(!DateOnly.TryParseExact(date.Text,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out var d)||!TimeOnly.TryParseExact(time.Text,"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out var start))throw new InvalidDataException(UiText.Get("TrainingInvalidDate"));var target=new TrainingTarget((TrainingScope)(scope.Selected+1),scope.Selected==1?players[person.Selected].Id:null,scope.Selected==2?(PlayerRole)(role.Selected+1):null,scope.Selected==3&&group.Selected>=0?plan.Groups[group.Selected].Id:null,exclude.GetSelectedItems().Select(i=>players[i].Id).ToArray());var e=exercises[exercise.Selected];var session=new TrainingSession(editing??Guid.NewGuid(),team,d,start,(int)minutes.Value,e.Code,(TrainingLoad)intensity.Selected,target,TrainingRules.Resolve(target,players,plan.Groups),responsible.Selected==0?null:staff[responsible.Selected-1].Id,opposition.ButtonPressed,e.Area==TrainingArea.SetPieces?new((Furvo.Core.Tactics.SetPieceKind)(routine.Selected+1)):null,e.Area==TrainingArea.Technology?service.Facility().Id:null,string.IsNullOrWhiteSpace(objective.Text)?UiText.Get("Exercise_"+e.Code):objective.Text,(int)frequency.Value);Save(plan with{Sessions=plan.Sessions.Where(s=>s.Id!=session.Id).Append(session).ToArray()});}catch(Exception e){SportsError(e,status);}}));
            if(_trainingTab==0){RenderTrainingGroups(content,plan,players,staff,Save);RenderTrainingDelegation(content,plan,staff,Save);}
        }
        catch(Exception e){GD.PushError(e.ToString());ShowError("TrainingLoadError",()=>NavigateCareer(CareerPage.Training),()=>NavigateCareer(CareerPage.Desktop));}
    }
    private void RenderTrainingGroups(VBoxContainer content,TrainingPlan plan,IReadOnlyList<TrainingCandidate> players,IReadOnlyList<TrainingStaff> staff,Func<TrainingPlan,bool> save)
    {
        var card=SportsCard(content,"TrainingGroups");card.AddChild(ClubUi.Text("TrainingGroupsTitle",UiText.Get("TrainingGroups"),18,"f1b96b"));var choose=new OptionButton{Name="TrainingGroupEdit"};choose.AddItem(UiText.Get("TrainingNewGroup"));foreach(var g in plan.Groups)choose.AddItem(g.Name);card.AddChild(choose);var name=new LineEdit{Name="TrainingGroupName",PlaceholderText=UiText.Get("Name")};card.AddChild(name);var objective=new LineEdit{Name="TrainingGroupObjective",PlaceholderText=UiText.Get("TrainingObjective")};card.AddChild(objective);var list=new ItemList{Name="TrainingGroupMembers",SelectMode=ItemList.SelectModeEnum.Multi,CustomMinimumSize=new Vector2(0,170)};foreach(var p in players)list.AddItem(p.Name);card.AddChild(list);
        var groupStaff=staff.Where(p=>p.Responsibilities.Contains(TrainingResponsibility.Group)).ToArray();var owner=new OptionButton{Name="TrainingGroupResponsible"};owner.AddItem(UiText.Get("TrainingUnassignedResponsible"));foreach(var person in groupStaff)owner.AddItem(person.Name=="TrainingHeadCoach"?UiText.Get(person.Name):person.Name);card.AddChild(owner);
        choose.ItemSelected+=i=>{list.DeselectAll();if(i==0){name.Text="";objective.Text="";return;}var selected=plan.Groups[(int)i-1];owner.Selected=selected.Responsible is {} responsible?Array.FindIndex(groupStaff,p=>p.Id==responsible)+1:0;name.Text=selected.Name;objective.Text=selected.Objective;for(var j=0;j<players.Count;j++)if(selected.Members.Contains(players[j].Id))list.Select(j,false);};
        card.AddChild(WindowUi.Button("TrainingSaveGroup",()=>{try{var old=choose.Selected==0?null:plan.Groups[choose.Selected-1];var value=new TrainingGroup(old?.Id??Guid.NewGuid(),name.Text,list.GetSelectedItems().Select(i=>players[i].Id).ToArray(),objective.Text,owner.Selected==0?null:groupStaff[owner.Selected-1].Id);var groups=plan.Groups.Where(g=>g.Id!=value.Id).Append(value).ToArray();save(plan with{Groups=groups,Sessions=plan.Sessions.Select(s=>s.Target.Scope==TrainingScope.Group&&s.Target.Group==value.Id?s with{Participants=TrainingRules.Resolve(s.Target,players,groups)}:s).ToArray()});}catch(Exception error){if(FindChild("TrainingStatus",true,false) is Label message)SportsError(error,message);}}));
    }
    private void RenderTrainingDelegation(VBoxContainer content,TrainingPlan plan,IReadOnlyList<TrainingStaff> staff,Func<TrainingPlan,bool> save)
    {
        var card=SportsCard(content,"TrainingDelegations");card.AddChild(ClubUi.Text("TrainingManagement",UiText.Get("TrainingManagement_"+plan.Management),18,"f1b96b"));
        foreach(var area in Enum.GetValues<TrainingResponsibility>()){card.AddChild(ClubUi.Text("TrainingResponsibilityLabel_"+area,UiText.Get("TrainingResponsibility_"+area),14));var available=staff.Where(s=>s.Id!=_workspace!.Career.Coach.Id.Value&&s.Responsibilities.Contains(area)).ToArray();var box=new OptionButton{Name="TrainingDelegate_"+area};box.AddItem(UiText.Get("TrainingManual"));foreach(var person in available)box.AddItem(person.Name);var selected=plan.Delegations.SingleOrDefault(d=>d.Area==area)?.Responsible;box.Selected=selected is null?0:Array.FindIndex(available,p=>p.Id==selected)+1;card.AddChild(box);if(available.Length==0)box.TooltipText=UiText.Get("TrainingNoQualifiedStaff");box.ItemSelected+=i=>save(plan with{Delegations=plan.Delegations.Where(d=>d.Area!=area).Concat(i==0?Array.Empty<TrainingDelegation>():new[]{new TrainingDelegation(area,available[(int)i-1].Id)}).ToArray()});}
    }
}
